export const codRemittanceData = [
  ...Array.from({ length: 20 }, (_, i) => {
    const grossCodValue = 5000 + i * 100;
    const shippingValue = 200 + i * 5;
    const adjustmentValue = (i % 2 === 0 ? -1 : 1) * (50 + i * 2);
    const netPayableValue = grossCodValue - shippingValue + adjustmentValue;

    return {
      status: "pending",
      merchant: `Merchant ${i + 1}`,
      grossCod: `₹${grossCodValue.toLocaleString()}`,
      shippingCharges: `₹${shippingValue.toLocaleString()}`,
      adjustments: `${adjustmentValue < 0 ? "-₹" : "₹"}${Math.abs(
        adjustmentValue
      ).toLocaleString()}`,
      netPayable: `${netPayableValue < 0 ? "-₹" : "₹"}${Math.abs(
        netPayableValue
      ).toLocaleString()}`,
      payoutCycle: i % 2 === 0 ? "Weekly" : "Monthly",
      paymentStatus: "Pending",
    };
  }),

  ...Array.from({ length: 20 }, (_, i) => {
    const adjustmentValue = (i % 2 === 0 ? -1 : 1) * (30 + i * 2);
    return {
      status: "paid",
      merchant: `Merchant ${i + 1}`,
      netPaidAmount: `₹${(4800 + i * 100 + adjustmentValue).toLocaleString()}`,
      paymentDate: `2025-08-${String((i % 30) + 1).padStart(2, "0")}`,
      transactionId: `TXN${10000 + i}`,
      processedBy: i % 2 === 0 ? "Admin" : "Finance",
    };
  }),

  ...Array.from({ length: 20 }, (_, i) => {
    const grossCodValue = 5500 + i * 120;
    const shippingValue = 250 + i * 5;
    const adjustmentValue = (i % 2 === 0 ? -1 : 1) * (40 + i * 3);
    const netPayableValue = grossCodValue - shippingValue + adjustmentValue;

    return {
      status: "upcoming",
      merchant: `Merchant ${i + 1}`,
      grossCod: `₹${grossCodValue.toLocaleString()}`,
      shippingCharges: `₹${shippingValue.toLocaleString()}`,
      adjustments: `${adjustmentValue < 0 ? "-₹" : "₹"}${Math.abs(
        adjustmentValue
      ).toLocaleString()}`,
      netPayable: `${netPayableValue < 0 ? "-₹" : "₹"}${Math.abs(
        netPayableValue
      ).toLocaleString()}`,
      payoutCycle: i % 2 === 0 ? "Weekly" : "Monthly",
      period: `Aug ${i + 1} - Aug ${i + 7}`,
    };
  }),
];

